window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-14891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαυρέσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3652 na letra ε · nº geral 14891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐπαυρίσκω.</p></section></article>\n<article id=\"entry-dgp-14892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαύρεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3653 na letra ε · nº geral 14892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 resultado; fruto 2 fruição; desfrute. 〈ἐπαυρίσκω〉</p></section></article>\n<article id=\"entry-dgp-14893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαύριον</h1><div class=\"entry-meta\"><span>DGP · ordem 3654 na letra ε · nº geral 14893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., tard. amanhã. 〈ἐπί, αὔριον〉</p></section></article>\n<article id=\"entry-dgp-14894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαυρίσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 3655 na letra ε · nº geral 14894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 ἐπηῦρον, inf. ἐπευρεῖν) 1 tomar parte em; desfrutar de algo, gen. 2 dispor dos benefícios de alguém, gen. 3 iron. fazer bom proveito de, gen. ou ac. 4 tocar; roçar; atingir, gen. ou ac. ♦ méd. (fut. ἐπαυρήσομαι, aor.2 ἐπηυρόμην, inf. ἐπαυρέσθαι) 5 colher o fruto de; tirar proveito de; desfrutar de, gen.; obter algo, ac., como proveito de, ἀπό e gen. 6 experimentar os inconvenientes de, ac. ou gen.; obter algo, ac., como resultado negativo de, gen. ou ἀπό e gen.</p></section></article>\n<article id=\"entry-dgp-14895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαϋτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3656 na letra ε · nº geral 14895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gritar 2 aclamar; aprovar 3 (cavalos) relinchar. 〈ἐπί, ἀϋτέω〉</p></section></article>\n<article id=\"entry-dgp-14896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαυτομολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3657 na letra ε · nº geral 14896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. ἐπαυτομολῆσαι) passar por si mesmo a, πρός e ac..</p></section></article>\n<article id=\"entry-dgp-14897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαυχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3658 na letra ε · nº geral 14897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐπηύχησα) 1 gloriar-se; gabar-se de; exultar por, dat. 2 ter confiança em, inf. 〈ἐπί, αὐχέω〉</p></section></article>\n<article id=\"entry-dgp-14898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαΰω</h1><div class=\"entry-meta\"><span>DGP · ordem 3659 na letra ε · nº geral 14898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. aor. ἐπαΰσας) responder com um grito.</p></section></article>\n<article id=\"entry-dgp-14899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαφάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3660 na letra ε · nº geral 14899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. tatear; roçar; acariciar, ac. ou gen. 〈ἐπαφή〉</p></section></article>\n<article id=\"entry-dgp-14900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3661 na letra ε · nº geral 14900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de tatear; toque; carícia 2 ação de tocar; manejo (da lira) 3 tratamento severo; punição; censura 4 indício 5 o sentido do tato; tato 6 Geom. ponto de contato; tangente. 〈ἐπί, ἁφή1〉</p></section></article>\n<article id=\"entry-dgp-14901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαφήσω</h1><div class=\"entry-meta\"><span>DGP · ordem 3662 na letra ε · nº geral 14901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐπαφίημι.</p></section></article>\n<article id=\"entry-dgp-14902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαφίημι</h1><div class=\"entry-meta\"><span>DGP · ordem 3663 na letra ε · nº geral 14902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπαφήσω etc.) 1 lançar; atirar algo, ac., contra ou sobre, dat. 2 impelir/tocar (o gado), ac., para, dat. 3 deixar escapar; emitir. 〈ἐπί, ἀφίημι〉</p></section></article>\n<article id=\"entry-dgp-14903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαφρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3664 na letra ε · nº geral 14903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. cobrir-se de espuma; espumar. 〈ἔπαφρος〉</p></section></article>\n<article id=\"entry-dgp-14904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαφρόδιτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3665 na letra ε · nº geral 14904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de charme; amável; cativante 2 favorito de Afrodite. 〈ἐπί, Ἀφροδίτη〉</p></section></article>\n<article id=\"entry-dgp-14905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπαφρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3666 na letra ε · nº geral 14905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coberto de espuma. 〈ἐπί, ἀφρός〉</p></section></article>\n<article id=\"entry-dgp-14906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαφύσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 3667 na letra ε · nº geral 14906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª sing. ἐπήφυσε) derramar sobre.</p></section></article>\n<article id=\"entry-dgp-14907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαχθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3668 na letra ε · nº geral 14907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pesado; oneroso 2 inoportuno; odioso. 〈ἐπί, ἄχθος〉</p></section></article>\n<article id=\"entry-dgp-14908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεάν</h1><div class=\"entry-meta\"><span>DGP · ordem 3669 na letra ε · nº geral 14908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐπήν.</p></section></article>\n<article id=\"entry-dgp-14909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέβαν</h1><div class=\"entry-meta\"><span>DGP · ordem 3670 na letra ε · nº geral 14909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor.2 ép. de ἐπιβαίνω.</p></section></article>\n<article id=\"entry-dgp-14910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεβήσατο</h1><div class=\"entry-meta\"><span>DGP · ordem 3671 na letra ε · nº geral 14910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἐπεβήσετο 3ª sing. aor. méd. de ἐπιβαίνω.</p></section></article>\n<article id=\"entry-dgp-14911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεβίων</h1><div class=\"entry-meta\"><span>DGP · ordem 3672 na letra ε · nº geral 14911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de ἐπιβιόω.</p></section></article>\n<article id=\"entry-dgp-14912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεβώσαντο</h1><div class=\"entry-meta\"><span>DGP · ordem 3673 na letra ε · nº geral 14912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. méd. jôn. de ἐπιβοάω.</p></section></article>\n<article id=\"entry-dgp-14913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεγγελάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3674 na letra ε · nº geral 14913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rir de; troçar de, dat. ou κατά e gen. 〈ἐπί, ἐγγελάω〉</p></section></article>\n<article id=\"entry-dgp-14914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεγείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 3675 na letra ε · nº geral 14914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπεγερῶ) 1 acordar; despertar 2 fazer despertar; excitar alguém; reavivar (um mal) ♦ pas. 3 acordar; despertar; part. perf. ἐπεγρηγορώς acordado; desperto. 〈ἐπί, ἐγείρω〉</p></section></article>\n<article id=\"entry-dgp-14915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεγερτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3676 na letra ε · nº geral 14915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 próprio para acordar; que faz despertar, gen. 2 estimulante; excitante. 〈ἐπεγείρω〉</p></section></article>\n<article id=\"entry-dgp-14916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεγκεράννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 3677 na letra ε · nº geral 14916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 misturar em acréscimo; acrescentar uma coisa, ac., a outra, dat. ♦ méd. 2 misturar 3 encarregar-se de. 〈ἐπί, ἐγκεράννυμι〉</p></section></article>\n<article id=\"entry-dgp-14917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέγρετο</h1><div class=\"entry-meta\"><span>DGP · ordem 3678 na letra ε · nº geral 14917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. sinc., ἐπεγρόμενος part. sinc., formas de aor.2 pas. de ἐπεγείρω.</p></section></article>\n<article id=\"entry-dgp-14918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεδέκοντο</h1><div class=\"entry-meta\"><span>DGP · ordem 3679 na letra ε · nº geral 14918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. jôn. de ἐπιδέχομαι.</p></section></article>\n<article id=\"entry-dgp-14919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεδεξάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 3680 na letra ε · nº geral 14919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. méd. jôn. de ἐπιδέχομαι.</p></section></article>\n<article id=\"entry-dgp-14920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέδομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3681 na letra ε · nº geral 14920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de ἐπεσθίω.</p></section></article>\n<article id=\"entry-dgp-14921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέδραμον</h1><div class=\"entry-meta\"><span>DGP · ordem 3682 na letra ε · nº geral 14921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de ἐπιτρέχω.</p></section></article>\n<article id=\"entry-dgp-14922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέδρη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3683 na letra ε · nº geral 14922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐφέδρα.</p></section></article>\n<article id=\"entry-dgp-14923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέεσσι</h1><div class=\"entry-meta\"><span>DGP · ordem 3684 na letra ε · nº geral 14923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. ép. de ἔπος.</p></section></article>\n<article id=\"entry-dgp-14924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέην</h1><div class=\"entry-meta\"><span>DGP · ordem 3685 na letra ε · nº geral 14924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. impf. ép. de ἔπειμι1.</p></section></article>\n<article id=\"entry-dgp-14925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεί</h1><div class=\"entry-meta\"><span>DGP · ordem 3686 na letra ε · nº geral 14925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj.; em crase, át. κἀπεί, jôn. κἠπεί (= καὶ ἐπεί), át. ἐπάν, jôn. ἐπήν, jôn. tard. ἐπέαν (= ἐπεὶ ἄν); ger. com partíc. γε, δή, ἤ, νυ, ῥα temporal 1 depois que; assim que; quando, com ind. aor. (real) ou inf. (dependentente de or. inf.), subj. (eventual fut. ou freq.; sem ἄν ou κε nos poetas) ou opt. (freq. no pas., ou oblíquo) 2 desde que; desde quando, com ind. (real) causal 3 visto que; dado que; porque, com ind. (real), ind. com ἄν (irreal), opt. com ἄν ou κε (potencial); às vezes com elipse verb. 4 visto que de outro modo; porque de outro modo, após or. negat. 5 pois, também, de fato; já que, no início de or. inter. que pressupõe resposta negat. 6 visto que; já que, após um voc., para justificar uma fala que vem em seguida conclusiva 7 logo; portanto; então, em frase imper. restritiva 8 ainda que; e entretanto; no entanto com partículas 9 αὐτίκ᾽ ἐπεί τε apenas, desde que, ἐπεὶ, ἐπειδὴ ou ἐπει­δὰν τάχιστα ou θᾶττον ou ἐπεὶ εὐθέως logo depois que, ἐπεὶ τὰ πρῶτα ou ἐπεὶ τὸ πρῶτον desde quando, depois que, ἐπεὶ ἄρα (tempo) depois que, quando então, (causa) dado que então, pois agora, ἐπεὶ οὖν quando então, ἐπεί γε ou ἐπεί γε δή ou ἐπεὶ δή, ἐπειδή dado que, porque de fato, ἐπεί περ e ἐπείπερ já que enfim; já que na verdade, ἐπεί νύ τοι pois certamente 1 αὐτὰρ ἐπεί ῥ᾽ εὔξαντο καὶ ἔσφαξαν καὶ ἔδειραν hom. logo depois que terminaram a prece, degolaram e cortaram em pedaços, λέγεται ἐπεὶ δὲ σφέας παραλαμβάνειν Ἕλληνας μεταιτέειν her. diz-se que [os argivos] depois que os gregos procuraram acolhê-los, pediram como recompensa (uma parte do comando), οὐ γὰρ ἔτ᾽ ἄλλη ἔσται θαλπωρή, ἐπεὶ ἂν σύ γε πότμον ἐπίσπῃς hom. porque não terei mais outro consolo quando tiveres cumprido teu destino, ἐγὼ δ᾽ ὀλίγον τε φίλον τε ἔρχομαι ἐπὶ νῆας, ἐπεί κε κάμω πολεμίζων hom. mas eu é que vou para os navios levando o pouco que me cabe, depois que me canso no combate, ἐπεὶ δ᾽ ἁμάρτῃ, κεῖνος οὐκέτ᾽ ἔστ᾽ ἀνὴρ ἄβουλος οὐδ᾽ ἄνολβος ὅστις ἐς κακὸν πεσὼν ἀκῆται sóf. quando comete uma falta, não mais destituído de vontade e de felicidade é o homem que, caído no infortúnio, sabe oferecer reparação, ἐπεὶ ζεύξειεν ὑφ᾽ ἅρμασιν ὠκέας ἵππους Ἕκτορα... δησάσκετο hom. cada vez que atrelava ao carro os cavalos, atava Heitor, ἐπεὶ διαβαίης, ἀπιέναι ἔφησθα xen. dizias que irias depois que tivesses atravessado 2 δέκατον μὲν ἔτος τόδ᾽ ἐπεὶ Μενέλαος ἠδ᾽ Ἀγαμέμνων στόλον ἦραν ésql. este é o décimo ano desde que Menelau e Agamenão conduziram uma frota, ὃς μάλα πολλὰ πλάγχθη ἐπεὶ Τροίης πτολίεθρον ἔπερσε hom. que muito vagueou desde quando destruiu a cidadela de Tróia 3 οὐκ ἔθελον δέξασθαι, ἐπεὶ πολὺ βούλομαι αὐτὴν οἴκοι ἔχειν hom. eu não quis receber [a recompensa] porque prefiro manter a jovem comigo, νῦν γὰρ χ᾽ Ἕκτορ᾽ ἕλοις ἐπεὶ μάλα τοι σχεδὸν ἔλθοι hom. neste momento poderias matar Heitor, pois ele viria bem próximo de ti, οὐ γὰρ ἂν σθένοντά γε εἷλέν μ᾽, ἐπεὶ οὐδ᾽ ἂν ὧδ᾽ ἔχοντ᾽, εἰ μὴ δόλῳ sóf. pois estando eu vigoroso, ele não me teria apanhado, porque nem nesse estado em que estou [ele o teria feito], a não ser por meio de dolo, ἐπεὶ καὶ μετὰ τὰ Τρωϊκὰ ἡ Ἑλλὰς ἔτι μετανίστατό τε καὶ κατῳκίζετο, ὥστε μὴ ἡσυχάσασαν αὐξηθῆναι tuc. [já no tempo da guerra de Tróia a Grécia contava com recursos medíocres] porque mesmo após a guerra de Tróia, a Hélada ainda sofria migrações e fundava colônias, de forma que não se desenvolveu com tranqüilidade, ἐπεὶ καὶ τοὺς μέγιστον φρονοῦντας ἐπὶ τῷ περὶ τούτων λέγειν, οὐ ταῦτα δοξάζειν ἀλλήλοις xen. [admirava-se que não percebessem claramente que o homem não pode resolver essas questões] pois mesmo os que se orgulham de falar melhor não concordam uns com os outros 4 οὐ γὰρ φιλόπονός ἐστιν, ἐπεὶ ἤρκει ἂν αὐτῷ τοῦτο ἀντὶ πάντων γυμνασίων xen. não é amigo do trabalho, pois do contrário isto lhe tomaria o lugar de todos os outros exercícios 5 ἐπεὶ τί νῦν ἕκατι δαιμόνων κυρῶ; ésql. pois até o momento o que recebi dos deuses? i.e., por que pediria aos deuses outros favores, se até agora nada obtive deles? ἐπεὶ τίς ὧδε τέκνοισιν Ζῆν᾽ ἄβουλον εἶδεν; sóf. porque enfim acaso alguém já viu Zeus desinteressar-se assim de seus filhos? 6 ξεῖν᾽, ἐπεὶ ἂρ δὴ ταῦτά μ᾽ ἀνείρεαι ἠδὲ μεταλλᾷς, μέλλεν μέν ποτε οἶκος ὅδ᾽ ἀφνειὸς καὶ ἀμύμων ἔμμεναι hom. meu hóspede, já que me fazes essas perguntas e garimpas respostas, [fica sabendo que] esta casa outrora era para ser rica e impecável, Ἕκτορ, ἐπεί με κατ᾽ αἶσαν ἐνείκεσας οὐδ᾽ ὑπὲρ αἶσαν: αἰεί τοι κραδίη πέλεκυς ὥς ἐστιν ἀτειρής hom. Heitor, visto que não me censuraste sem razão nem além da razão, [ouve]: teu coração é sempre inflexível como um machado 7 ἐπεὶ δίδαξον sóf. ensina-me, então! ἐπεὶ φέρ᾽ εἰπέ sóf. portanto, vamos lá, fala! 8 ἀδύνατος [εἰμί], ἐπεὶ ἐβουλόμην ἂν οἷός τ᾽ εἶναι plat. sou incapaz, e contudo eu gostaria de ser capaz, αἰσχυνοίμην ἂν τοῦτο ὁμολογεῖν, ἐπεὶ πολλοί γέ φασι plat. eu, pelo menos, teria vergonha de concordar com isso, ainda que muita gente afirme concordar.</p></section></article>\n<article id=\"entry-dgp-14926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείγετο</h1><div class=\"entry-meta\"><span>DGP · ordem 3687 na letra ε · nº geral 14926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. pas., ἔπειγον impf. at. poét., de ἐπείγω.</p></section></article>\n<article id=\"entry-dgp-14927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείγω</h1><div class=\"entry-meta\"><span>DGP · ordem 3688 na letra ε · nº geral 14927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἤπειγον, fut. ἐπείξω, aor. ἤπειξα; pas. aor. ἠπείχθην) 1 prensar com seu peso; comprimir; oprimir 2 acossar; pressionar; coagir; atacar: ὡς δ᾽ ὅτε δύω κύνε ἢ κεμάδ᾽ ἢ λαγωὸν ἐπείγετον hom. como quando dois cães acossam uma corça ou uma lebre, ἐπείγετο γὰρ βελέεσσι hom. porque era pressionado pelas setas 3 (leite) coagular: ὀπὸς γάλα λευκὸν ἐπειγόμενος συνέπηξεν hom. o suco de figo coagulaçndo o branco leite, fá-lo coalhar 4 empurrar bruscamente; sacudir; (vento) impelir: ἐπείγει ἲς ἀνέμοιο hom. a força do vento impele [as ondas] 5 apressar-se: ἐπείγετε δ᾽ ὦνον ὁδαίων hom. apressai a compra da provisão da viagem, ᾗ νοεῖς ἔπειγέ νυν sóf. apressa-te pois em fazer o que tens em mente 6 ser urgente; urgir: τῶν ἀρχαιρεσίων ἐπειγόντων plat. já que a eleição dos magistrados era urgente, τὰ ἐπείγοντα plut. as tarefas urgentes, as emergências, οὐκ ἐπείγει não há urgência em, inf. ♦ méd. 7 apressar-se: ἐπειγόμενοι τὸν ἐμόν γάμον hom. apressados com meu casamento, τὸν πλοῦν ἐπείγεσθαι tuc. apressar sua travessia.</p></section></article>\n<article id=\"entry-dgp-14928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπειδάν,</h1><div class=\"entry-meta\"><span>DGP · ordem 3689 na letra ε · nº geral 14928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ἐπειδὴ ἄν, conj. temp. 1 quando; cada vez que, com subj. (eventual freq.): ἐπειδὰν δὲ κρύψωσι γῇ, ἀνὴρ λέγει ἐπ᾽ αὐτοῖς ἔπαινον tuc. quando cobrem com terra [os mortos em combate], um homem pronuncia em honra deles um elogio 2 depois que, com subj. (eventual fut.): ταῦτα ἐπειδὰν περὶ τοῦ γένους εἴπω, ἐρῶ dem. disso eu falarei, depois que tiver falado sobre a família, ἄφρων ἔσται ἡ ψυχή, ἐπειδὰν τοῦ ἄφρονος σώματος δίχα γένηται xen. a alma será privada da razão quando estiver separada do corpo privado de razão.</p></section></article>\n<article id=\"entry-dgp-14929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπειδή</h1><div class=\"entry-meta\"><span>DGP · ordem 3690 na letra ε · nº geral 14929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. 1 (tempo) depois que, com ind. (real), subj. ou inf. com ἄν (eventual freq., sem ἄν nos poetas), opt. (eventual freq. no pas.), inf. subord. a outro inf.; ἐπειδὰν πρῶτον, τὸ πρῶτον, τὰ πρῶτα, τάχιστα, θᾶττον ou εὐθὺς ἐπειδάν logo que; assim que 2 (causa) já que; visto que, com ind., para justificar um ato de fala realizado a seguir 1 ἐπειδὴ γὰρ ἐξηπάτησθε μὲν ὑμεῖς ὑπὸ τοῦ Φιλλίπου, ἐξηπάτηντο δὲ οἱ ταλαίπωροι Φωκεῖς καὶ ἀνῄρηντο αἱ πόλεις αὐτῶν, τί ἐγένετο; dem. depois que fostes enganados por Filipe, e que os infelizes fociões também se deixaram enganar, e que suas cidades foram destruídas, que aconteceu? ἐπειδή τι ἐμφάγοιεν, ἀνίσταντο xen. depois que tomavam a refeição, levantavam-se, ἐπειδὴ πρὸς τὸ φῶς ἔλθοι, ὁρᾶν οὐδ᾽ ἂν ἓν δύνασθαι [οὐκ οἴει]; plat. depois que ele viesse para a luz, não supões que ele não poderia ver coisa alguma? ἐπειδὴ τόν γε δαμάσσεται (subj. aor. ép.) ὠκὺς ὀϊστός μιν θῶες δαρδάπτουσιν hom. depois que seta rápida o domina, os chacais o devoram, ἐπειδὴ δὲ κατὰ σχολὴν σκέψασθαι, κόπτεσθαί τε καὶ ὀδύρεσθαι plat. após examinar com vagar, golpeou-se e gemeu, ἐπειδὴ πρῶτα τομὴν ἐν ὄρεσσι λέλοιπεν hom. logo que, nas montanhas, ele [o ramo] foi separado do tronco 2 ἐπειδὴ σὺ βούλει ἀποκρίνου plat. já que queres, responde!, ὦ φίλ᾽, ἐπειδὴ ταῦτά μ᾽ ἀνέμνησας, φασί hom. amigo, já que me fizeste recordar isso, [ouve:] dizem. 〈ἐπεί, δή〉</p></section></article>\n<article id=\"entry-dgp-14930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεῖδον</h1><div class=\"entry-meta\"><span>DGP · ordem 3691 na letra ε · nº geral 14930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de ἐφοράω.</p></section></article>\n<article id=\"entry-dgp-14931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείη</h1><div class=\"entry-meta\"><span>DGP · ordem 3692 na letra ε · nº geral 14931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. opt. pres. de ἔπειμι1.</p></section></article>\n<article id=\"entry-dgp-14932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπειή</h1><div class=\"entry-meta\"><span>DGP · ordem 3693 na letra ε · nº geral 14932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. poét. já que em verdade. 〈ἐπεί, ἦ〉</p></section></article>\n<article id=\"entry-dgp-14933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεικάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3694 na letra ε · nº geral 14933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπεικάσω) tentar adivinhar; conjeturar: ὡς ou ὅσ᾽ ἐπεικάσαι [πάρεστι] pelo que se pode conjecturar, ὡς γ᾽ ἐπεικάζειν ἐμέ sóf. pelo que eu posso conjecturar. 〈ἐπί, εἰκάζω〉</p></section></article>\n<article id=\"entry-dgp-14934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεικώς, υῖα, ός</h1><div class=\"entry-meta\"><span>DGP · ordem 3695 na letra ε · nº geral 14934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át., cf. ἐπέοικα.</p></section></article>\n<article id=\"entry-dgp-14935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπειμι1</h1><div class=\"entry-meta\"><span>DGP · ordem 3696 na letra ε · nº geral 14935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. ἐπεῖναι, impf. ἐπῆν etc.) 1 estar sobre ou acima de, dat, ἐπί e dat. ou gen.: μηκέτι κάρη ὤμοισιν ἐπείη hom. que a cabeça não mais esteja sobre os ombros, σῆμα δ᾽ οὐκ ἐπῆν κύκλῳ ésql. não havia sinal sobre o escudo, ἐπῆν στύγος στρατῷ ésql. a dor abatia-se sobre o exército 2 estar à frente; estar à testa de; comandar: τίς δὲ ποιμάνωρ ἔπεστι; ésql. qual chefe os comanda?, ἔπεστί σφι δεσπότης νόμος her. como senhor, à frente deles está a lei 3 estar depois; vir em seguida; suceder: ἔτι πού τις ἐπέσσεται hom. em seguida virá ainda alguém, i.e., haverá sucessores, οὐδέ τι δειλὸν γῆρας ἐπῆν hes. em seguida não vinha a mísera velhice, οἱ ἐπεσσόμενοι tuc. os pósteros, ἐπεσσόμενοι ἄνθρωποι her. as gerações futuras 4 vir como conseqüência; resultar: ποινὰ γὰρ ἐπέσται ésql. o castigo sobrevirá, εἰ δ᾽ ἔπεστι νέμεσις οὐ λέγω sóf. que seja a Nêmesis eu nego, νυνὶ πλεῖ κέρδος ἐπέσται ar. navega agora, haverá lucro 5 (quantia) somar-se; juntar-se a, ἐπί e dat.: χιλιάδες δὲ ἔπεισι ἐπὶ ταύτῃσι ἑπτά her. e milhares se juntam a esses sete. 〈ἐπί, εἰμί〉</p></section></article>\n<article id=\"entry-dgp-14936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπειμι2</h1><div class=\"entry-meta\"><span>DGP · ordem 3697 na letra ε · nº geral 14936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. ἐπιέναι, impf. ἐπῄειν, fut. ἔπειμι) 1 aproximar-se; avançar; apresentar-se: νὺξ ἐπήει sóf. a noite se aproximava, ἐκέλευον ἐπιέναι tuc. convidaram[-no] a aproximar-se [da tribuna], ὁ ἐπιών sóf. aquele que vem, o primeiro a vir 2 ir sobre ou contra; avançar contra; atacar, dat. ou ἐπί e dat., ac. ou ἐπί, πρός e ac.: οἱ ἐπιόντες her. os assaltantes, ὅς μοι ἔπεισιν hom. [Enéias] que avança contra mim 3 (abstrato) desabar; abater-se sobre, ac.: οἷός σε χειμὼν ἔπεισι ésql. qual tempestade vai desabar sobre ti, πρίν μιν γῆρας ἔπεισιν hom. antes que a velhice o atinja 4 ir ou vir em seguida; vir depois; suceder: κύματα βάντ᾽ ἐπιόντα τε sóf. as vagas que vêm e se sucedem, ὁ ἐπιὼν χρόνος xen. o futuro, ἡ ἐπιοῦσα [ἡμέρα] o dia seguinte, o amanhã, τῆς ἐπιούσης νυκτός plat. a próxima noite, ἡ ἐπιοῦσα ὥρα τοῦ ἔτους dem. a próxima estação do ano, τῶν ἐπιόντων ἕνεκα dem. por causa das conseqüências, ὁ ἐπιών sóf. o descendente 5 (idéia) vir ao espírito de; ocorrer a alguém, dat.: ἂν ὑμῖν ὀρθῶς ἐπίῃ σκοπεῖν dem. se vos vem ao espírito examinar retamente, τὸ ἐπιόν ou τοὐπιόν plat. o que vem à mente, ὅ τι ἂν ἀπὸ τοῦ αὐτομάτου ἐπίῃ μοι xen. o que quer que se apresentava espontaneamente a meu espírito 6 ir através; percorrer; passar em revista: φώκας μέν τοι πρῶτον ἀριθμήσει καὶ ἔπεισιν hom. primeiro irá contar suas focas e passá-las em revista, ὁ μὲν Νικίας τοιάδε παρακελευόμενος ἅμα ἐπῄει τὸ στράτευμα tuc. ao mesmo tempo que proferia tais recomendações, Nícias percorria as fileiras do exército. 〈ἐπί, εἶμι〉</p></section></article>\n<article id=\"entry-dgp-14937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεῖναι</h1><div class=\"entry-meta\"><span>DGP · ordem 3698 na letra ε · nº geral 14937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. de ἔπειμι1 ou inf. aor.2 jôn. de ἐφίημι.</p></section></article>\n<article id=\"entry-dgp-14938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 3699 na letra ε · nº geral 14938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só inf. pres. méd. ἐπείνυσθαι) jôn. = ἐπιέννυμι.</p></section></article>\n<article id=\"entry-dgp-14939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπειξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3700 na letra ε · nº geral 14939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pressa; azáfama; solicitude. 〈ἐπείγω〉</p></section></article>\n<article id=\"entry-dgp-14940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείπερ</h1><div class=\"entry-meta\"><span>DGP · ordem 3701 na letra ε · nº geral 14940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἐπεί περ cf. ἐπεί.</p></section></article>\n<article id=\"entry-dgp-14941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεῖπον</h1><div class=\"entry-meta\"><span>DGP · ordem 3702 na letra ε · nº geral 14941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. ἐπειπεῖν) 1 falar em acréscimo; acrescentar ao que foi dito 2 pronunciar algo, ac., contra alguém, dat. 3 salientar o contrário; falar em contraposição 4 pronunciar. 〈ἐπί, εἶπον〉</p></section></article>\n<article id=\"entry-dgp-14942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπειρα</h1><div class=\"entry-meta\"><span>DGP · ordem 3703 na letra ε · nº geral 14942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de πείρω.</p></section></article>\n<article id=\"entry-dgp-14943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείρα</h1><div class=\"entry-meta\"><span>DGP · ordem 3704 na letra ε · nº geral 14943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. de πειράω.</p></section></article>\n<article id=\"entry-dgp-14944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείρομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3705 na letra ε · nº geral 14944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. (fut. ἐπερήσομαι, aor.2 ἐπηρόμην, perf. ἐπερέσθαι) 1 perguntar; interrogar alguém, ac., sobre algo, ac. ou περί e gen.: ἐπ. τὴν γνώμην plat. pedir a opinião, ἐπήροντο τὸν θεὸν εἰ tuc. perguntaram ao deus se 2 perguntar de novo algo, ac.</p></section></article>\n<article id=\"entry-dgp-14945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπειρυσάμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 3706 na letra ε · nº geral 14945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. méd. jôn. de ἐπερύω.</p></section></article>\n<article id=\"entry-dgp-14946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπειρωτάω</h1><div class=\"entry-meta\"><span>DGP · ordem 3707 na letra ε · nº geral 14946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐπερωτάω.</p></section></article>\n<article id=\"entry-dgp-14947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπειρώτεον</h1><div class=\"entry-meta\"><span>DGP · ordem 3708 na letra ε · nº geral 14947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. jôn. de ἐπερωτάω.</p></section></article>\n<article id=\"entry-dgp-14948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπειρώτημα, ἐπειρώτησις</h1><div class=\"entry-meta\"><span>DGP · ordem 3709 na letra ε · nº geral 14948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐπερώτημα, ἐπερώτησις.</p></section></article>\n<article id=\"entry-dgp-14949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπεισα</h1><div class=\"entry-meta\"><span>DGP · ordem 3710 na letra ε · nº geral 14949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de πείθω.</p></section></article>\n<article id=\"entry-dgp-14950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισάγω</h1><div class=\"entry-meta\"><span>DGP · ordem 3711 na letra ε · nº geral 14950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 introduzir em acréscimo; introduzir uma pessoa, ac., além de ou em acréscimo ou substituição de outra, dat.: ἐπ. ἑταίρας εἰς τὴν οἰκίαν dem. levar cortesãs para dentro de casa (em acréscimo à esposa), ἐπ. τὴν Κλεοπάτραν τῇ Ὀλυμπιάδι at. introduzir [em casa] Cleópatra em acréscimo a Olímpia 2 trazer uma coisa, ac., em lugar de outra, dat. 3 trazer para a cena; mostrar em cena uma nova peça 4 introduzir em acréscimo algo (novo); introduzir por inovação ♦ méd. 5 introduzir em sua casa ♦ pas. 6 οἱ ἐπεισαχθέντες d.h. os cidadãos recém-admitidos, os novos cidadãos. 〈ἐπί, εἰσάγω〉</p></section></article>\n<article id=\"entry-dgp-14951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισαγωγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3712 na letra ε · nº geral 14951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">introdução suplementar 2 passagem para introduzir. 〈ἐπεισάγω〉</p></section></article>\n<article id=\"entry-dgp-14952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισαγώγιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3713 na letra ε · nº geral 14952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é importado; de importação ♦ τὰ ἐπεισαγώγιμα 2 objetos importados. 〈ἐπεισάγω〉</p></section></article>\n<article id=\"entry-dgp-14953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείσακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3714 na letra ε · nº geral 14953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 proveniente do estrangeiro; importado 2 estrangeiro. 〈ἐπεισάγω〉</p></section></article>\n<article id=\"entry-dgp-14954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισβαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3715 na letra ε · nº geral 14954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">avançar até; entrar em, εἰς e ac. 〈ἐπί, εἰσ­βαίνω〉</p></section></article>\n<article id=\"entry-dgp-14955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισβάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 3716 na letra ε · nº geral 14955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acrescentar algo, ac., a, dat. 2 atirar-se novamente sobre; invadir outra vez, dat. 〈ἐπί, εἰσβάλλω〉</p></section></article>\n<article id=\"entry-dgp-14956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισδέχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3717 na letra ε · nº geral 14956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aceitar em acréscimo; aceitar a mais.</p></section></article>\n<article id=\"entry-dgp-14957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείσειμι</h1><div class=\"entry-meta\"><span>DGP · ordem 3718 na letra ε · nº geral 14957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. ἐπεισιέναι, part. ἐπεισιών, impf. 3ª pl. ἐπεισήϊσαν) 1 entrar outra vez; entrar depois de outrem 2 vir após; ocorrer depois; sobrevir 3 apresentar-se de novo; reaparecer em cena 4 adentrar, penetrar em. 〈ἐπί, εἴσειμι〉</p></section></article>\n<article id=\"entry-dgp-14958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισέρχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3719 na letra ε · nº geral 14958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 ἐπεισῆλθον etc.) 1 apresentar-se como intruso ou como recém-chegado ou como estrangeiro em algum lugar, dat., ac. ou εἰς e ac. 2 entrar depois de outro; vir após um outro 3 (coisa) vir de fora; ser importado 4 vir em seguida ao espírito; sobrevir a alguém, dat. ou ac. 5 (costume) introduzir-se tardiamente. 〈ἐπί, εἰσέρχομαι〉</p></section></article>\n<article id=\"entry-dgp-14959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισκαλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3720 na letra ε · nº geral 14959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">convocar por cooptação.</p></section></article>\n<article id=\"entry-dgp-14960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισκυκλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3721 na letra ε · nº geral 14960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. pas. ἐπεισεκυκλήθην) 1 fazer rolar ou deslizar uma coisa, ac., após outra, dat. 2 empilhar uma coisa, ac., sobre outra, ἐπί e dat. 〈ἐπί, εἰσκυκλέω〉</p></section></article>\n<article id=\"entry-dgp-14961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισκωμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3722 na letra ε · nº geral 14961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐπεισεκώμασα, perf. ἐπεισκεκώμακα) 1 irromper em coro festivo; precipitar-se com gritos e com alegria; fazer uma irrupção alegre e tumultuada 2 introduzir-se indevidamemente.</p></section></article>\n<article id=\"entry-dgp-14962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισόδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3723 na letra ε · nº geral 14962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que vem em acréscimo; acessório 2 adventício; estranho 3 estranho ao assunto; episódico ♦ τὸ ἐπεισόδιον 4 acessório; acréscimo 5 sobremesa 6 Ret. digressão 7 Dram. episódio, porção dialogada entre dois cantos corais 8 incidente. 〈ἐπί, εἴσοδος〉</p></section></article>\n<article id=\"entry-dgp-14963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισοδιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3724 na letra ε · nº geral 14963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ret. 1 introduzir uma digressão ou um episódio 2 variar pela introdução de episódios ou de incidentes. 〈ἐπεισόδιος〉</p></section></article>\n<article id=\"entry-dgp-14964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπείσοδος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3725 na letra ε · nº geral 14964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nova entrada; nova chegada; intervenção 2 introdução; ingresso. 〈ἐπί, εἴσοδος〉</p></section></article>\n<article id=\"entry-dgp-14965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισπαίω</h1><div class=\"entry-meta\"><span>DGP · ordem 3726 na letra ε · nº geral 14965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lançar-se sobre; cair sobre; irromper em, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-14966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισπηδάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3727 na letra ε · nº geral 14966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saltar; irromper 2 saltar sobre, ac. 3 usurpar, dat.</p></section></article>\n<article id=\"entry-dgp-14967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισπίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 3728 na letra ε · nº geral 14967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπεισπεσοῦμαι) 1 cair em ou sobre; irromper em, dat. ou εἰς e ac. 2 cair sucessivamente sobre, dat. 〈ἐπί, εἰσπίπτω〉</p></section></article>\n<article id=\"entry-dgp-14968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισπλέω-ῶ,</h1><div class=\"entry-meta\"><span>DGP · ordem 3729 na letra ε · nº geral 14968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ἐπεσπλέω (fut. ἐπεσπλευσοῦμαι) 1 navegar de novo para; navegar 2 sobrevir com um navio ou frota 3 navegar contra; atacar.</p></section></article>\n<article id=\"entry-dgp-14969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισρέω</h1><div class=\"entry-meta\"><span>DGP · ordem 3730 na letra ε · nº geral 14969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) escorrer em ou sobre; fluir; transbordar.</p></section></article>\n<article id=\"entry-dgp-14970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισφέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 3731 na letra ε · nº geral 14970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπεισοίσω etc.) 1 trazer em acréscimo; trazer a mais; trazer como novidade: ὁ ἐπεισφερόμενος [νόμος] artt. a lei recém-introduzida, ἐπὶ τῷ αἰεὶ ἐπεισφερομένῳ πρήγμα τι her. fato que sobrevém, fato 2 trazer sem cessar uma coisa, ac., após outra ♦ méd. 3 trazer sucessivamente para si: ἐπ. μαρτυρία tuc. apresentar uma sucessão de testemunhos em favor próprio. 〈ἐπί, εἰσφέρω〉</p></section></article>\n<article id=\"entry-dgp-14971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεισφρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3732 na letra ε · nº geral 14971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">introduzir ainda alguém ou algo, ac., em, dat.</p></section></article>\n<article id=\"entry-dgp-14972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπειτα</h1><div class=\"entry-meta\"><span>DGP · ordem 3733 na letra ε · nº geral 14972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 (sucessão) em seguida; depois; então: τὸν δ᾽ ἠμείβετ᾽ ἔπ. hom. então lhe respondeu, τοῦ μέν τε σθένος ὦρσεν, ἔπ. δέ τ᾽ οὐ προσαμύνει hom. excitou sua força e depois não pode resistir-lhe, πρῶτα... ἔπ. δέ, πρῶτα μέν... αὐτὰρ ἔπ., πρῶτα μέν... ἔπ. δέ, πρῶτον μέν... ἔπ. primeiro... depois...; ὁ ἔπ. χρόνος ou τὸ ἔπ. ou τὰ ἔπ. eur. o futuro, οἱ ἔπειτα ésql. ou οἱ ἔπ. ἐσόμενοι plat. a posteridade, ἐν ᾧ νῦν παρόντι καὶ ἐν τῷ ἔπ. plat. no presente e no futuro imediato 2 (dedução) então; nesse caso: εἰ δὲ ἐτέον ἀγορεύεις, ἐξ ἄρα δή τοι ἔπ. φρένας ὤλεσαν hom. se tuas palavras são verdadeiras, então os deuses destruíram teu raciocínio 3 (seqüência lógica) então: νῆσος ἔπειτά τις ἔστι hom. então há uma ilha, ἔπ. δῆτα δοῦλος ὢν κόμην ἔχεις; ar. e então, és escravo e ainda assim tens essa longa cabeleira?, ἔπ. τοῦ δέει; ar. e então, de que precisas? 4 (restrição) entretanto; apesar disso; mesmo assim: ὅστις ἀνθρώπου φύσιν βλαστὼν ἔπ. μὴ κατ᾽ ἄνθρωπον φρονῇ sóf. aquele que, nascido com natureza humana, não tem entretanto sentimentos de homem, ἔπ. οὐκ οἴει; xen. e mesmo assim não acreditas? 〈ἐπί, εἶτα〉</p></section></article>\n<article id=\"entry-dgp-14973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπειτεν</h1><div class=\"entry-meta\"><span>DGP · ordem 3734 na letra ε · nº geral 14973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e dór. = ἔπειτα.</p></section></article>\n<article id=\"entry-dgp-14974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπειχθῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 3735 na letra ε · nº geral 14974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. pas. de ἐπείγω.</p></section></article>\n<article id=\"entry-dgp-14975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεῖχον</h1><div class=\"entry-meta\"><span>DGP · ordem 3736 na letra ε · nº geral 14975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. de ἐπέχω.</p></section></article>\n<article id=\"entry-dgp-14976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκβαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3737 na letra ε · nº geral 14976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 ἐπεξέβην) desembarcar; descer em; ir para.</p></section></article>\n<article id=\"entry-dgp-14977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκβοηθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3738 na letra ε · nº geral 14977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. aor. ἐπεκβοηθησάντων) acorrer em socorro.</p></section></article>\n<article id=\"entry-dgp-14978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκδιδάσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 3739 na letra ε · nº geral 14978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπεκδιδάξω) 1 ensinar a mais 2 explicar detalhadamente.</p></section></article>\n<article id=\"entry-dgp-14979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκδιηγέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3740 na letra ε · nº geral 14979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 explicar de novo 2 explicar detalhadamente.</p></section></article>\n<article id=\"entry-dgp-14980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκδρομή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3741 na letra ε · nº geral 14980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">expedição; excursão. 〈ἐπί, ἐκδραμεῖν〉</p></section></article>\n<article id=\"entry-dgp-14981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέκεινα</h1><div class=\"entry-meta\"><span>DGP · ordem 3742 na letra ε · nº geral 14981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 além; mais longe; posteriomente: τὸ ἐπέκεινα e τὰ ἐπέκεινα, com crase τοῦπέκεινα e τἀπέ­κεινα as regiões situadas para além, a parte ulterior, ἐν τοῖς ἐπ. χρόνοις isócr. nos tempos ulteriores, i. e., até esta época ♦ prep. 2 além de, gen.: τὰ ἐπ. τῆς Εὐρώπης her. os países situados além da Europa, ἔτι ἐπ. τῆς οὐσίας ὑπερέχοντος plat. sendo ainda superior à essência.</p></section></article>\n<article id=\"entry-dgp-14982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκέκλετο</h1><div class=\"entry-meta\"><span>DGP · ordem 3743 na letra ε · nº geral 14982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. com red. de ἐπικέλομαι.</p></section></article>\n<article id=\"entry-dgp-14983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">επεκέκλητο</h1><div class=\"entry-meta\"><span>DGP · ordem 3744 na letra ε · nº geral 14983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">m.-q.-perf. pas. de ἐπικαλέω.</p></section></article>\n<article id=\"entry-dgp-14984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέκερσα</h1><div class=\"entry-meta\"><span>DGP · ordem 3745 na letra ε · nº geral 14984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐπικείρω.</p></section></article>\n<article id=\"entry-dgp-14985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκθέω</h1><div class=\"entry-meta\"><span>DGP · ordem 3746 na letra ε · nº geral 14985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐπεξέθεον) atirar-se sobre; lançar-se sobre; atacar.</p></section></article>\n<article id=\"entry-dgp-14986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπέκπλοος-ους, όου-ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3747 na letra ε · nº geral 14986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partida de uma frota contra o inimigo; ataque por mar. 〈ἐπί, ἔκπλους〉</p></section></article>\n<article id=\"entry-dgp-14987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκτείνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3748 na letra ε · nº geral 14987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπεκτενῶ) 1 estender mais; esticar: ἐπ. λόγους plut. prolongar os discursos 2 Gram. alongar (quantidade da sílaba ou forma da palavra) 3 intr. (país) estender-se para além de, gen. ♦ pas. 4 no perf. (palavra) ser alongado. 〈ἐπί, ἐκτείνω〉</p></section></article>\n<article id=\"entry-dgp-14988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκτρέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 3749 na letra ε · nº geral 14988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 ἐπεξέδραμον) fazer uma surtida contra alguém, dat.; desabalar sobre.</p></section></article>\n<article id=\"entry-dgp-14989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκφέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 3750 na letra ε · nº geral 14989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3ª sing. ἐπεξέφερε) 1 executar; produzir contra; suscitar contra 2 buscar conseguir à força (um contrato).</p></section></article>\n<article id=\"entry-dgp-14990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπεκχωρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3751 na letra ε · nº geral 14990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3ª sing. ἐπεξεχώρει) avançar em seguida.</p></section></article>\n";
